import{_ as t,o as s,c as e,ag as i}from"./chunks/framework.CmaAMB6e.js";const u=JSON.parse('{"title":"系统设计学习环境","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/setup.md","filePath":"system-design/setup.md","lastUpdated":null}'),l={name:"system-design/setup.md"};function n(d,a,r,o,p,h){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="系统设计学习环境" tabindex="-1">系统设计学习环境 <a class="header-anchor" href="#系统设计学习环境" aria-label="Permalink to &quot;系统设计学习环境&quot;">​</a></h1><blockquote><p>目标：确认前置就绪 + 准备设计工具。系统设计是「纸面功夫」，不需要复杂环境，但需要正确的思维工具。约 15 分钟。</p></blockquote><h2 id="前置检查" tabindex="-1">前置检查 <a class="header-anchor" href="#前置检查" aria-label="Permalink to &quot;前置检查&quot;">​</a></h2><ul><li>[ ] 已掌握至少一个后端语言（Python/Java/Node.js）</li><li>[ ] 已理解数据库基础（SQL/索引/事务）</li><li>[ ] 了解 Linux 基本操作（可选但推荐）</li></ul><blockquote><p>本线是「架构思维」训练，编码不是重点，<strong>设计和论证</strong>是重点。</p></blockquote><h2 id="工具准备" tabindex="-1">工具准备 <a class="header-anchor" href="#工具准备" aria-label="Permalink to &quot;工具准备&quot;">​</a></h2><h3 id="_1-画图工具-选一" tabindex="-1">1. 画图工具（选一） <a class="header-anchor" href="#_1-画图工具-选一" aria-label="Permalink to &quot;1. 画图工具（选一）&quot;">​</a></h3><ul><li><strong>Excalidraw</strong>（免费，手绘风，最适合架构图）：excalidraw.com</li><li><strong>draw.io</strong>（免费，经典）：app.diagrams.net</li><li><strong>Mermaid</strong>（Markdown 内嵌，适合与笔记一起存）：本系统即支持</li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[客户端] --&gt; B[负载均衡]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[Web 服务]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[(数据库)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; E[(缓存)]</span></span></code></pre></div><h3 id="_2-容量估算工具" tabindex="-1">2. 容量估算工具 <a class="header-anchor" href="#_2-容量估算工具" aria-label="Permalink to &quot;2. 容量估算工具&quot;">​</a></h3><ul><li>计算器 + 单位换算表（QPS/存储/带宽）</li><li>常用参考值（记住量级感）： <ul><li>单机 QPS：简单查询 ~1000，带缓存 ~10000</li><li>单表行数：百万级没问题，千万级需注意</li><li>网络带宽：1 Gbps ≈ 125 MB/s</li></ul></li></ul><h3 id="_3-练习流程-每次设计遵循" tabindex="-1">3. 练习流程（每次设计遵循） <a class="header-anchor" href="#_3-练习流程-每次设计遵循" aria-label="Permalink to &quot;3. 练习流程（每次设计遵循）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 需求澄清（2 分钟）      ← 问清功能/非功能/规模</span></span>
<span class="line"><span>2. 容量估算（3 分钟）      ← QPS/存储/带宽</span></span>
<span class="line"><span>3. 高层设计（5 分钟）      ← 画架构图</span></span>
<span class="line"><span>4. 深入设计（5 分钟）      ← 选型 + 关键路径</span></span>
<span class="line"><span>5. 权衡与演进（3 分钟）    ← 瓶颈/取舍/扩展</span></span></code></pre></div><h2 id="就绪验证" tabindex="-1">就绪验证 <a class="header-anchor" href="#就绪验证" aria-label="Permalink to &quot;就绪验证&quot;">​</a></h2><p>系统设计不写代码，所以「环境搭好了」的判据不是装了什么，而是——<strong>你能不能在 20 分钟内独立走完一遍完整流程</strong>。</p><p>拿一个你熟悉的小系统练手（比如「设计一个短链服务」），给自己计时：</p><ul><li>[ ] 能在 2 分钟内问清需求边界（日活多少？读写比？延迟要求？）</li><li>[ ] 能估算出量级（QPS 是几百还是几万？一年存多少 GB？）</li><li>[ ] 能画出架构图（客户端 → 负载均衡 → 服务 → 存储 / 缓存）</li><li>[ ] 能说清至少一个瓶颈点和应对方案</li><li>[ ] 能说出至少一处「我这样选，放弃了什么」</li></ul><table tabindex="0"><thead><tr><th>结果</th><th>下一步</th></tr></thead><tbody><tr><td>五项全中</td><td>前置达标，直接从 01 开始</td></tr><tr><td>卡在第 1、2 项</td><td>先补 <a href="/learning/system-design/concepts/02-capacity-estimation">02 容量估算</a>，把量级感建立起来</td></tr><tr><td>卡在第 3、4 项</td><td>建议先学 <a href="/learning/database/">数据库</a> 和 <a href="/learning/linux/">Linux</a>，再回来——本线放在它们之后会顺畅很多</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这条线不建议零基础直接学</p><p>系统设计是<strong>在前置技能之上的综合思维训练</strong>。没写过后端、没碰过数据库索引和事务，看这里的每一篇都会觉得「道理都懂，但不知道为什么这么选」。 这也是首页把它排在第 6 位的原因。</p></div><h2 id="前端类比锚点" tabindex="-1">前端类比锚点 <a class="header-anchor" href="#前端类比锚点" aria-label="Permalink to &quot;前端类比锚点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构</th><th>系统设计</th></tr></thead><tbody><tr><td>组件拆分</td><td>服务拆分</td></tr><tr><td>状态管理分层</td><td>数据流设计</td></tr><tr><td>性能优化（缓存/懒加载）</td><td>缓存/CDN/分片</td></tr><tr><td>错误边界</td><td>熔断/降级</td></tr><tr><td>Monorepo</td><td>微服务</td></tr></tbody></table><p>完成前置确认后，回到 <code>learning-path.md</code> 开始第一个概念。</p>`,22)])])}const g=t(l,[["render",n]]);export{u as __pageData,g as default};
